Output: {"predicate": "moles_product", "unit": "mol", "context": "stoichiometry", "bindings": {"reaction": {"value": "calcium_carbonate_decomposition", "unit": "label"}, "reactant": {"value": "CaCO3", "unit": "label"}, "product": {"value": "CaO", "unit": "label"}, "mass_reactant": {"value": 5.711, "unit": "g"}}}

