Output: {"predicate": "volume_gas_product", "unit": "L", "context": "stoichiometry", "bindings": {"reaction": {"value": "ethane_combustion", "unit": "label"}, "reactant": {"value": "O2", "unit": "label"}, "product": {"value": "CO2", "unit": "label"}, "moles_reactant": {"value": 0.07353, "unit": "mol"}, "other_reactants": {"value": "excess", "unit": "condition"}, "gas_conditions": {"value": "stp", "unit": "condition"}}}

